_PATTERN = re.compile(
    r"^(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?$"
)
_MULTIPLIERS = (86400, 3600, 60, 1)


def parse_duration(s):
    """Parse a duration string such as '1h30m' into seconds."""
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    text = s.strip()
    if not text:
        raise ValueError("empty duration")

    match = _PATTERN.fullmatch(text)
    if match is None or all(amount is None for amount in match.groups()):
        raise ValueError(f"invalid duration: {s!r}")

    total = 0
    for amount, multiplier in zip(match.groups(), _MULTIPLIERS):
        if amount is not None:
            total += int(amount) * multiplier
    return total
